(() => {
  'use strict';

  /*
   * BuyerOS Actions V151
   *
   * Controlled write boundary.
   *
   * No action is executed merely because it is proposed.
   * Every write requires an explicit confirmation token
   * generated by this runtime.
   */

  const VERSION = '151';

  const STORAGE = Object.freeze({
    things:
      'still-ownership-passports-v83',

    documents:
      'still-buyeros-documents-v132',

    audit:
      'still-buyeros-action-audit-v151'
  });

  const proposals = new Map();

  const ALLOWED_THING_FIELDS =
    new Set([
      'title',
      'kind',
      'brand',
      'manufacturer',
      'model',
      'modelName',
      'serialNumber',
      'serial',
      'business',
      'store',
      'location',
      'purchaseDate',
      'purchasedOn',
      'purchasePrice',
      'warrantyUntil',
      'returnBy',
      'renewalAt',
      'nextActionAt',
      'condition',
      'notes'
    ]);

  function graphV152() {
    return window.StillBuyerOSGraphV152 || null;
  }

  function clean(value) {
    return String(
      value ?? ''
    ).trim();
  }

  function clone(value) {
    if (
      value === undefined
    ) {
      return undefined;
    }

    return JSON.parse(
      JSON.stringify(value)
    );
  }

  function readArray(key) {
    try {
      const value =
        JSON.parse(
          localStorage.getItem(key) ||
          '[]'
        );

      return Array.isArray(value)
        ? value
        : [];
    } catch {
      return [];
    }
  }

  function writeArray(
    key,
    value
  ) {
    localStorage.setItem(
      key,
      JSON.stringify(value)
    );

    window.dispatchEvent(
      new CustomEvent(
        'still:buyeros-data-updated',
        {
          detail:{
            key,
            count:value.length,
            source:'actions-v151'
          }
        }
      )
    );
  }

  function uuid(prefix) {
    if (
      globalThis.crypto &&
      typeof crypto.randomUUID ===
        'function'
    ) {
      return (
        prefix +
        '-' +
        crypto.randomUUID()
      );
    }

    return (
      prefix +
      '-' +
      Date.now() +
      '-' +
      performance.now()
        .toString(36)
        .replace('.','')
    );
  }

  function thingById(id) {
    return readArray(
      STORAGE.things
    ).find(
      item =>
        String(
          item.id ||
          ''
        ) ===
        String(id)
    ) || null;
  }

  function documentById(id) {
    return readArray(
      STORAGE.documents
    ).find(
      item =>
        String(
          item.id ||
          ''
        ) ===
        String(id)
    ) || null;
  }

  function audit(entry) {
    const log =
      readArray(
        STORAGE.audit
      );

    log.push({
      id:
        uuid('audit'),

      at:
        new Date()
          .toISOString(),

      ...clone(entry)
    });

    /*
     * Keep local audit bounded.
     * This is not analytics or telemetry.
     */
    writeArray(
      STORAGE.audit,
      log.slice(-500)
    );
  }

  function publicProposal(
    proposal
  ) {
    return {
      id:
        proposal.id,

      action:
        proposal.action,

      summary:
        proposal.summary,

      details:
        clone(
          proposal.details
        ),

      risk:
        proposal.risk,

      createdAt:
        proposal.createdAt,

      expiresAt:
        proposal.expiresAt,

      requiresConfirmation:
        true
    };
  }

  function actionDefinition(
    action,
    args
  ) {
    switch (action) {
      case 'update_thing': {
        const thingId =
          clean(
            args?.thingId
          );

        const changes =
          args?.changes;

        if (
          !thingId ||
          !changes ||
          typeof changes !==
            'object' ||
          Array.isArray(changes)
        ) {
          throw Object.assign(
            new Error(
              'thingId and changes are required'
            ),
            {
              code:
                'INVALID_ARGUMENT'
            }
          );
        }

        const thing =
          thingById(
            thingId
          );

        if (!thing) {
          throw Object.assign(
            new Error(
              'Thing not found'
            ),
            {
              code:'NOT_FOUND'
            }
          );
        }

        const sanitized = {};

        Object.entries(
          changes
        ).forEach(
          ([key,value]) => {
            if (
              !ALLOWED_THING_FIELDS
                .has(key)
            ) {
              return;
            }

            sanitized[key] =
              value === null
                ? ''
                : clean(value);
          }
        );

        if (
          !Object.keys(
            sanitized
          ).length
        ) {
          throw Object.assign(
            new Error(
              'No supported changes supplied'
            ),
            {
              code:
                'INVALID_ARGUMENT'
            }
          );
        }

        return {
          risk:'standard',

          summary:
            `Update ${thing.title || 'ownership record'}`,

          details:{
            thingId,
            thingTitle:
              thing.title || '',
            changes:sanitized
          },

          execute() {
            const data =
              readArray(
                STORAGE.things
              );

            const index =
              data.findIndex(
                item =>
                  item.id ===
                  thingId
              );

            if (index < 0) {
              throw new Error(
                'Thing disappeared before confirmation'
              );
            }

            const before =
              clone(
                data[index]
              );

            data[index] = {
              ...data[index],
              ...sanitized,
              updatedAt:
                new Date()
                  .toISOString()
            };

            writeArray(
              STORAGE.things,
              data
            );

            window.dispatchEvent(
              new CustomEvent(
                'still:ownership-updated',
                {
                  detail:{
                    thingId,
                    source:
                      'actions-v151'
                  }
                }
              )
            );

            return {
              before,
              after:
                clone(
                  data[index]
                )
            };
          }
        };
      }

      case 'add_service': {
        const thingId =
          clean(
            args?.thingId
          );

        const thing =
          thingById(
            thingId
          );

        if (!thing) {
          throw Object.assign(
            new Error(
              'Thing not found'
            ),
            {
              code:'NOT_FOUND'
            }
          );
        }

        const title =
          clean(
            args?.title
          );

        if (!title) {
          throw Object.assign(
            new Error(
              'Service title is required'
            ),
            {
              code:
                'INVALID_ARGUMENT'
            }
          );
        }

        const service = {
          id:
            uuid('service'),

          title,

          serviceType:
            clean(
              args?.serviceType
            ),

          providerName:
            clean(
              args?.providerName
            ),

          occurredOn:
            clean(
              args?.occurredOn
            ),

          cost:
            clean(
              args?.cost
            ),

          notes:
            clean(
              args?.notes
            ),

          createdAt:
            new Date()
              .toISOString()
        };

        return {
          risk:'standard',

          summary:
            `Add service to ${thing.title || 'ownership record'}`,

          details:{
            thingId,
            thingTitle:
              thing.title || '',
            service
          },

          execute() {
            const data =
              readArray(
                STORAGE.things
              );

            const index =
              data.findIndex(
                item =>
                  item.id ===
                  thingId
              );

            if (index < 0) {
              throw new Error(
                'Thing disappeared before confirmation'
              );
            }

            const history =
              Array.isArray(
                data[index]
                  .serviceHistory
              )
                ? [
                    ...data[index]
                      .serviceHistory
                  ]
                : [];

            history.push(
              service
            );

            data[index] = {
              ...data[index],
              serviceHistory:
                history,
              updatedAt:
                new Date()
                  .toISOString()
            };

            writeArray(
              STORAGE.things,
              data
            );

            window.dispatchEvent(
              new CustomEvent(
                'still:ownership-updated',
                {
                  detail:{
                    thingId,
                    source:
                      'actions-v151'
                  }
                }
              )
            );

            return {
              thingId,
              service:
                clone(service)
            };
          }
        };
      }

      case 'link_document': {
        const documentId =
          clean(
            args?.documentId
          );

        const thingId =
          clean(
            args?.thingId
          );

        const doc =
          documentById(
            documentId
          );

        const thing =
          thingById(
            thingId
          );

        if (!doc) {
          throw Object.assign(
            new Error(
              'Document not found'
            ),
            {
              code:'NOT_FOUND'
            }
          );
        }

        if (!thing) {
          throw Object.assign(
            new Error(
              'Thing not found'
            ),
            {
              code:'NOT_FOUND'
            }
          );
        }

        return {
          risk:'standard',

          summary:
            `Link document to ${thing.title || 'ownership record'}`,

          details:{
            documentId,
            documentTitle:
              doc.title ||
              doc.type ||
              '',
            thingId,
            thingTitle:
              thing.title ||
              ''
          },

          execute() {
            const docs =
              readArray(
                STORAGE.documents
              );

            const index =
              docs.findIndex(
                item =>
                  item.id ===
                  documentId
              );

            if (index < 0) {
              throw new Error(
                'Document disappeared before confirmation'
              );
            }

            const before =
              clone(
                docs[index]
              );

            docs[index] = {
              ...docs[index],

              thingId,
              relatedThingId:
                thingId,

              relatedThing:
                thing.title ||
                '',

              updatedAt:
                new Date()
                  .toISOString()
            };

            writeArray(
              STORAGE.documents,
              docs
            );

            return {
              before,
              after:
                clone(
                  docs[index]
                )
            };
          }
        };
      }

      case 'delete_thing': {
        const thingId =
          clean(
            args?.thingId
          );

        const thing =
          thingById(
            thingId
          );

        if (!thing) {
          throw Object.assign(
            new Error(
              'Thing not found'
            ),
            {
              code:'NOT_FOUND'
            }
          );
        }

        return {
          risk:'destructive',

          summary:
            `Delete ${thing.title || 'ownership record'}`,

          details:{
            thingId,
            thingTitle:
              thing.title ||
              ''
          },

          execute() {
            const data =
              readArray(
                STORAGE.things
              );

            const index =
              data.findIndex(
                item =>
                  item.id ===
                  thingId
              );

            if (index < 0) {
              throw new Error(
                'Thing disappeared before confirmation'
              );
            }

            const removed =
              data.splice(
                index,
                1
              )[0];

            writeArray(
              STORAGE.things,
              data
            );

            window.dispatchEvent(
              new CustomEvent(
                'still:ownership-updated',
                {
                  detail:{
                    thingId,
                    deleted:true,
                    source:
                      'actions-v151'
                  }
                }
              )
            );

            return {
              removed:
                clone(removed)
            };
          }
        };
      }

      default:
        throw Object.assign(
          new Error(
            `Unknown BuyerOS action: ${action}`
          ),
          {
            code:'UNKNOWN_ACTION'
          }
        );
    }
  }

  function propose(
    action,
    args = {}
  ) {
    try {
      const definition =
        actionDefinition(
          clean(action),
          clone(args) || {}
        );

      const id =
        uuid('proposal');

      const confirmationToken =
        uuid('confirm');

      const now =
        Date.now();

      const proposal = {
        id,
        action:
          clean(action),

        summary:
          definition.summary,

        details:
          definition.details,

        risk:
          definition.risk,

        confirmationToken,

        createdAt:
          new Date(now)
            .toISOString(),

        expiresAt:
          new Date(
            now +
            5 * 60 * 1000
          ).toISOString(),

        execute:
          definition.execute
      };

      proposals.set(
        id,
        proposal
      );

      audit({
        phase:'proposed',
        proposalId:id,
        action:
          proposal.action,
        risk:
          proposal.risk,
        summary:
          proposal.summary
      });

      return {
        ok:true,
        proposal:
          publicProposal(
            proposal
          ),

        /*
         * Token is returned to the UI runtime.
         * It is not embedded inside the public proposal.
         */
        confirmationToken
      };
    } catch (error) {
      return {
        ok:false,

        proposal:null,

        confirmationToken:null,

        error:{
          code:
            error?.code ||
            'ACTION_ERROR',

          message:
            error?.message ||
            'Unable to propose BuyerOS action'
        }
      };
    }
  }

  function cancel(
    proposalId
  ) {
    const id =
      clean(
        proposalId
      );

    const proposal =
      proposals.get(id);

    if (!proposal) {
      return {
        ok:false,
        error:{
          code:'NOT_FOUND',
          message:
            'Action proposal not found'
        }
      };
    }

    proposals.delete(id);

    audit({
      phase:'cancelled',
      proposalId:id,
      action:
        proposal.action,
      summary:
        proposal.summary
    });

    return {
      ok:true
    };
  }

  function confirm(
    proposalId,
    confirmationToken
  ) {
    const id =
      clean(
        proposalId
      );

    const proposal =
      proposals.get(id);

    if (!proposal) {
      return {
        ok:false,
        error:{
          code:'NOT_FOUND',
          message:
            'Action proposal not found'
        }
      };
    }

    if (
      new Date(
        proposal.expiresAt
      ).getTime() <
      Date.now()
    ) {
      proposals.delete(id);

      audit({
        phase:'expired',
        proposalId:id,
        action:
          proposal.action
      });

      return {
        ok:false,
        error:{
          code:'EXPIRED',
          message:
            'Action proposal has expired'
        }
      };
    }

    if (
      clean(
        confirmationToken
      ) !==
      proposal.confirmationToken
    ) {
      audit({
        phase:
          'confirmation_rejected',

        proposalId:id,

        action:
          proposal.action
      });

      return {
        ok:false,
        error:{
          code:
            'CONFIRMATION_REQUIRED',

          message:
            'Explicit confirmation is required'
        }
      };
    }

    try {
      const result =
        proposal.execute();

      proposals.delete(id);

      audit({
        phase:'executed',
        proposalId:id,
        action:
          proposal.action,
        risk:
          proposal.risk,
        summary:
          proposal.summary
      });

      return {
        ok:true,

        action:
          proposal.action,

        result:
          clone(result),

        error:null
      };
    } catch (error) {
      audit({
        phase:'failed',
        proposalId:id,
        action:
          proposal.action,
        message:
          error?.message ||
          'Execution failed'
      });

      return {
        ok:false,

        action:
          proposal.action,

        result:null,

        error:{
          code:
            error?.code ||
            'EXECUTION_FAILED',

          message:
            error?.message ||
            'BuyerOS action failed'
        }
      };
    }
  }

  function listPending() {
    return [
      ...proposals.values()
    ].map(
      publicProposal
    );
  }

  function auditLog(
    limit = 100
  ) {
    const count =
      Math.min(
        500,
        Math.max(
          1,
          Number.parseInt(
            limit,
            10
          ) || 100
        )
      );

    return readArray(
      STORAGE.audit
    )
      .slice(-count)
      .reverse();
  }

  const api =
    Object.freeze({
      version:
        VERSION,

      propose,

      confirm,

      cancel,

      listPending,

      auditLog,

      supportedActions:
        Object.freeze([
          'update_thing',
          'add_service',
          'link_document',
          'delete_thing'
        ])
    });

  Object.defineProperty(
    window,
    'StillBuyerOSActionsV151',
    {
      value:api,
      enumerable:false,
      writable:false,
      configurable:false
    }
  );

  window.dispatchEvent(
    new CustomEvent(
      'still:buyeros-actions-ready',
      {
        detail:{
          version:
            VERSION,

          actions:
            api.supportedActions
        }
      }
    )
  );
})();
